// 双堆维护中位数：偶数个时输出下中位数
struct MedianFinder {
 priority_queue<int> lo; // 大根堆，元素 <= hi
 priority_queue<int, vector<int>, greater<int>> hi; // 小根堆
 void add(int x) {
 lo.push(x);
 hi.push(lo.top()); lo.pop();
 if (hi.size() > lo.size()) { lo.push(hi.top()); hi.pop();}
}
 int median() const { return lo.top();}
};
