import heapq


class MedianFinder:
    '''双堆维护中位数：偶数个时输出下中位数。'''

    def __init__(self):
        self.lo = []  # 大根堆（存负数），元素 <= hi
        self.hi = []  # 小根堆

    def add(self, x):
        heapq.heappush(self.lo, -x)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo):
            heapq.heappush(self.lo, -heapq.heappop(self.hi))

    def median(self):
        return -self.lo[0]


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    mf = MedianFinder()
    for x in data[1:1 + n]:
        mf.add(x)
        print(mf.median())

