#include <bits/stdc++.h>
using namespace std;
// 双栈求值：支持 + - * / 和括号，非负整数
long long apply_op(long long a, long long b, char op) {
 if (op == '+') return a + b;
 if (op == '-') return a - b;
 if (op == '*') return a * b;
 return a / b; // C++ 向零取整
}
int prec(char op) {
 if (op == '+' || op == '-') return 1;
 if (op == '*' || op == '/') return 2;
 return 0;
}
long long evaluate(const string &s) {
 vector<long long> vals;
 vector<char> ops;
 auto apply = [&]() {
 long long b = vals.back(); vals.pop_back();
 long long a = vals.back(); vals.pop_back();
 char op = ops.back(); ops.pop_back();
 vals.push_back(apply_op(a, b, op));
};
 for (size_t i = 0; i < s.size();) {
 char ch = s[i];
 if (isdigit(ch)) {
 long long v = 0;
 while (i < s.size() && isdigit(s[i])) { v = v * 10 + (s[i] - '0'); ++i;}
 vals.push_back(v);
} else if (ch == '(') { ops.push_back(ch); ++i;}
 else if (ch == ')') {
 while (!ops.empty() && ops.back()!= '(') apply();
 ops.pop_back(); ++i;
} else if (ch == '+' || ch == '-' || ch == '*' || ch == '/') {
 while (!ops.empty() && ops.back()!= '(' && prec(ops.back()) >= prec(ch)) apply();
 ops.push_back(ch); ++i;
} else { ++i;} // 跳过空格等
}
 while (!ops.empty()) apply();
 return vals.back();
}
int main() {
 ios::sync_with_stdio(false);
 cin.tie(nullptr);
 string s, line;
 while (getline(cin, line)) s += line;
 cout << evaluate(s) << '\n';
 return 0;
}

template_python:
def apply_op(ops, vals):
    op = ops.pop()
    b = vals.pop()
    a = vals.pop()
    if op == '+':
        vals.append(a + b)
    elif op == '-':
        vals.append(a - b)
    elif op == '*':
        vals.append(a * b)
    elif op == '/':
        vals.append(int(a / b))  # 向零取整，和 C++ 一致


def evaluate(s):
    '''双栈求值：支持 + - * / 和括号，非负整数。'''
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}
    ops, vals = [], []
    i, n = 0, len(s)
    while i < n:
        ch = s[i]
        if ch.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            vals.append(int(s[i:j]))
            i = j
            continue
        elif ch == '(':
            ops.append(ch)
        elif ch == ')':
            while ops and ops[-1] != '(':
                apply_op(ops, vals)
            ops.pop()
        elif ch in prec:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[ch]:
                apply_op(ops, vals)
            ops.append(ch)
        i += 1
    while ops:
        apply_op(ops, vals)
    return vals[-1]


if __name__ == '__main__':
    import sys
    s = sys.stdin.read().replace(' ', '').strip()
    print(evaluate(s))

