}
// 哨兵节点合并两条有序链表
ListNode* merge_two(ListNode *l1, ListNode *l2) {
 ListNode dummy;
 ListNode *cur = &dummy;
 while (l1 && l2) {
 if (l1->val <= l2->val) { cur->next = l1; l1 = l1->next;}
 else { cur->next = l2; l2 = l2->next;}
 cur = cur->next;
}
 cur->next = l1? l1: l2;
 return dummy.next;
}
