def is_bst(a):
    '''a 是层序数组（-1 表示空），判断是否为二叉搜索树（严格左<根<右）。'''
    if not a or a[0] == -1:
        return True

    def dfs(i, lo, hi):
        if i >= len(a) or a[i] == -1:
            return True
        v = a[i]
        if (lo is not None and v <= lo) or (hi is not None and v >= hi):
            return False
        return dfs(2 * i + 1, lo, v) and dfs(2 * i + 2, v, hi)

    return dfs(0, None, None)


