 int u, v; cin >> u >> v;
 g[u].push_back(v); g[v].push_back(u);
}
 int LOG = 1;
 while ((1 << LOG) <= n) ++LOG;
 vector<vector<int>> up(LOG, vector<int>(n + 1));
 vector<int> depth(n + 1, 0), parent(n + 1, 0);
 vector<int> st = {1}; // 迭代 DFS
 parent[1] = 1; up[0][1] = 1;
 while (!st.empty()) {
 int u = st.back(); st.pop_back();
 for (int v: g[u]) if (v!= parent[u]) {
 parent[v] = u; depth[v] = depth[u] + 1; up[0][v] = u;
 st.push_back(v);
}
}
 for (int k = 1; k < LOG; ++k)
 for (int v = 1; v <= n; ++v)
 up[k][v] = up[k - 1][up[k - 1][v]];
 auto lca = [&](int a, int b) {
 if (depth[a] < depth[b]) swap(a, b);
 int diff = depth[a] - depth[b];
 for (int k = 0; diff; ++k, diff >>= 1)
 if (diff & 1) a = up[k][a];
 if (a == b) return a;
 for (int k = LOG - 1; k >= 0; --k)
 if (up[k][a]!= up[k][b]) { a = up[k][a]; b = up[k][b];}
 return up[0][a];
};
 int q; cin >> q;
 while (q--) { int a, b; cin >> a >> b; cout << lca(a, b) << '\n';}
 return 0;
}

