// 返回 (最远点, 距离)
pair<int, int> farthest(const vector<vector<int>> &g, int start) {
 int n = (int)g.size() - 1;
 vector<int> dist(n + 1, -1);
 dist[start] = 0;
 vector<int> st = {start};
 while (!st.empty()) {
 int u = st.back(); st.pop_back();
 for (int v: g[u]) if (dist[v] == -1) {
 dist[v] = dist[u] + 1;
 st.push_back(v);
}
}
 int u = start;
 for (int i = 1; i <= n; ++i) if (dist[i] > dist[u]) u = i;
 return {u, dist[u]};
}
int main() {
 ios::sync_with_stdio(false);
 cin.tie(nullptr);
 int n;
 if (!(cin >> n)) return 0;
 vector<vector<int>> g(n + 1);
 for (int i = 0; i < n - 1; ++i) {
 int u, v; cin >> u >> v;
 g[u].push_back(v); g[v].push_back(u);
}
 int a = farthest(g, 1).first;
 cout << farthest(g, a).second << '\n';
