}

#include <bits/stdc++.h>
using namespace std;
// 由前序+中序建树，返回后序遍历。值互不相同。
vector<int> build_post(const vector<int> &pre, const vector<int> &ino) {
 unordered_map<int, int> pos;
 for (int i = 0; i < (int)ino.size(); ++i) pos[ino[i]] = i;
 vector<int> res;
 function<void(int, int, int, int)> dfs = [&](int pl, int pr, int il, int ir) {
 if (pl >= pr) return;
 int root = pre[pl];
 int k = pos[root];
 int left_len = k - il;
 dfs(pl + 1, pl + 1 + left_len, il, k);
 dfs(pl + 1 + left_len, pr, k + 1, ir);
 res.push_back(root);
};
 dfs(0, (int)pre.size(), 0, (int)ino.size());
 return res;
}
int main() {
 ios::sync_with_stdio(false);
 cin.tie(nullptr);
 int n;
 if (!(cin >> n)) return 0;
 vector<int> pre(n), ino(n);
 for (int i = 0; i < n; ++i) cin >> pre[i];
 for (int i = 0; i < n; ++i) cin >> ino[i];
 auto r = build_post(pre, ino);
 for (int i = 0; i < (int)r.size(); ++i)
 cout << r[i] << (i + 1 == (int)r.size()? '\n': ' ');
 return 0;
}
